'use client';
import {useEffect,useMemo,useState} from 'react';
import {PRIVILEGES,PRIVILEGE_LABELS} from '@/lib/permissions';
import {Package,LayoutDashboard,ArrowRightLeft,Warehouse,Users,BarChart3,Settings,Plus,Search,Edit,Trash2,LogOut,Download,RefreshCw,ShieldCheck,Receipt,FileText,DollarSign,Power,Printer,Upload} from 'lucide-react';
import {BarChart,Bar,XAxis,YAxis,Tooltip,ResponsiveContainer,PieChart,Pie,Cell,CartesianGrid,Legend,AreaChart,Area} from 'recharts';
import {showAlert,showConfirm,showPrompt,showToast} from './swal';

type Any=any;
const money=(value:number,currency='RWF')=>new Intl.NumberFormat(undefined,{style:'currency',currency,minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(value||0));
const MEASUREMENT_UNITS=['Piece','Unit','Box','Pack','Carton','Kg','Gram','Tonne','Litre','Millilitre','Meter','Centimeter','Roll','Pair','Set','Dozen','Bottle','Bag'];

export default function DashboardClient({user}:Any){
 const [data,setData]=useState<Any>(null),[tab,setTab]=useState('dashboard'),[loading,setLoading]=useState(true),[search,setSearch]=useState(''),[status,setStatus]=useState('All'),[store,setStore]=useState('All'),[modal,setModal]=useState<string|null>(null),[selected,setSelected]=useState<Any>(null),[lastReceipt,setLastReceipt]=useState<string|null>(null);
 async function load(){setLoading(true);try{const r=await fetch('/api/bootstrap',{cache:'no-store'});if(r.status===401){location.href='/login';return}const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Could not load inventory data');setData(d)}catch(e){await showAlert('Unable to load inventory',e instanceof Error?e.message:'Could not load inventory data','error')}finally{setLoading(false)}}
 useEffect(()=>{load()},[]);
 useEffect(()=>{
  let alive=true;
  const applySettings=(next:any)=>{
   if(!next||!alive)return;
   setData((prev:any)=>prev?{...prev,settings:{...prev.settings,...next}}:prev);
  };
  const refreshSettings=async()=>{
   try{const r=await fetch('/api/settings',{cache:'no-store'});const d=await r.json().catch(()=>null);if(r.ok&&d)applySettings(d)}catch{}
  };
  const onLocal=(e:any)=>applySettings(e?.detail);
  window.addEventListener('inventory-settings-changed',onLocal);
  let channel:any=null;
  try{channel=new BroadcastChannel('inventorypro-settings');channel.onmessage=(e:any)=>applySettings(e?.data)}catch{}
  const timer=window.setInterval(refreshSettings,3000);
  return()=>{alive=false;window.removeEventListener('inventory-settings-changed',onLocal);window.clearInterval(timer);if(channel)channel.close()};
 },[]);
 function p(k:string){return data?.permissions?.[k]===true}
 function notify(m:string){void showToast(m)}
 async function api(url:string,method:string,body?:Any){try{const r=await fetch(url,{method,headers:body?{'content-type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined});const d=await r.json().catch(()=>({}));if(r.status===401){location.href='/login';return null}if(!r.ok){await showAlert('Request failed',d.error||`Request failed (${r.status})`,'error');return null}await load();if(d.receipt)setLastReceipt(d.receipt);notify(d.receipt?'Stock issued. Receipt generated.':'Saved successfully');return d}catch(e){await showAlert('Connection error',e instanceof Error?e.message:'The request could not be completed.','error');return null}}
 async function logout(){try{await fetch('/api/auth/logout',{method:'POST'})}finally{location.href='/login'}}
 if(loading)return <div className="auth"><div>Loading inventory system…</div></div>;
 const items=data.items||[],stores=data.stores||[],transactions=data.transactions||[],currency=data.settings?.currency||'RWF',systemName=data.settings?.systemName||'InventoryPro HQ',logo=data.settings?.logoDataUrl||'/company-logo.svg',taxRate=data.settings?.taxRate===undefined||data.settings?.taxRate===null?null:Number(data.settings.taxRate);
 const filtered=items.filter((i:Any)=>(`${i.name} ${i.id} ${i.barcode}`).toLowerCase().includes(search.toLowerCase())&&(status==='All'||i.status===status)&&(store==='All'||i.storeId===store));
 const valuation=items.reduce((n:number,i:Any)=>n+i.quantity*(i.sellPrice??i.unitPrice??0),0),units=items.reduce((n:number,i:Any)=>n+i.quantity,0),low=items.filter((i:Any)=>i.status==='Low Stock').length,out=items.filter((i:Any)=>i.status==='Out of Stock').length;
 const nav=[['dashboard','Dashboard',LayoutDashboard,'viewDashboard'],['inventory','Inventory',Package,'viewInventory'],['movements','Movements',ArrowRightLeft,'viewMovements'],['receipt','Generate Receipt',Receipt,'generateReceipt'],['proforma','Proforma Invoice',FileText,'generateProforma'],['proforma-history','Proforma History',FileText,'viewProformas'],['receipt-history','Receipt History',FileText,'viewReceipts'],['activities','Activities',DollarSign,'viewActivities'],['audit','System Audit',ShieldCheck,'viewAudit'],['stores','Stores',Warehouse,'viewStores'],['rbac','Users & RBAC',Users,'manageUsers'],['reports','Reports',BarChart3,'viewReports'],['settings','Settings',Settings,'viewDashboard'],['posted-notes','Posted Notes',FileText,'viewPostedNotes']];
 return <div className="app"><aside className="sidebar"><div className="brand" style={{display:"flex",alignItems:"center",gap:9,overflowWrap:"anywhere"}}>{<img src={logo} alt="System logo" style={{width:36,height:36,objectFit:"contain",flexShrink:0}}/>}<span style={{color:"inherit",fontWeight:700}}>{systemName}</span></div><div className="nav">{nav.map(([key,label,Icon,required]:Any)=>{if(required&&!p(required))return null;return <button key={key} className={tab===key?'active':''} onClick={()=>setTab(key)}><Icon size={17}/>{label}</button>})}</div><div style={{position:'absolute',bottom:20,left:20,right:20}}><button className="nav button" onClick={logout}><LogOut size={17}/>Sign out</button></div></aside><main className="content"><div className="mobile-nav">{nav.filter((x:Any)=>!x[3]||p(x[3])).map(([k,l]:Any)=><button onClick={()=>setTab(k)} key={k}>{l}</button>)}</div><header className="topbar"><div><h1>{nav.find((n:Any)=>n[0]===tab)?.[1]}</h1><span className="muted">Operational inventory control</span></div><div className="user-chip"><div><b>{data.user?.name||user.name}</b><div className="muted" style={{fontSize:12}}>{data.user?.role||user.role}</div></div><div className="avatar">{(data.user?.name||user.name).split(' ').map((x:string)=>x[0]).join('').slice(0,2)}</div></div></header>{lastReceipt&&<div className="panel" style={{marginBottom:14,display:'flex',justifyContent:'space-between',alignItems:'center'}}><span><b>Receipt ready:</b> {lastReceipt.split('/').pop()}</span><a className="primary" href={lastReceipt} target="_blank">Open receipt</a></div>}{tab==='dashboard'&&<Dashboard items={items} stores={stores} transactions={transactions} currency={currency}/>} {tab==='inventory'&&<Inventory currency={currency} items={filtered} stores={stores} categories={data.categories} search={search} setSearch={setSearch} status={status} setStatus={setStatus} store={store} setStore={setStore} p={p} setModal={setModal} setSelected={setSelected} api={api}/>} {tab==='movements'&&<Movements items={items} stores={stores} transactions={transactions} p={p} setModal={setModal} setSelected={setSelected}/>} {tab==='receipt'&&<ReceiptBuilder currency={currency} items={items} stores={stores} p={p} api={api} setTab={setTab} setLastReceipt={setLastReceipt} taxRate={taxRate}/>} {tab==='proforma'&&<ProformaBuilder currency={currency} items={items} stores={stores} systemName={systemName} logo={logo} user={data.user} api={api} taxRate={taxRate} />} {tab==='proforma-history'&&<ProformaHistory proformas={data.proformas||[]} stores={stores} currency={currency} api={api} systemName={systemName} logo={logo} user={data.user} hasPrivilege={p}/>} {tab==='receipt-history'&&<ReceiptHistory currency={currency} receipts={data.receipts||[]} transactions={transactions} stores={stores}/>} {tab==='activities'&&<Activities currency={currency} activities={data.activities||[]} p={p} api={api}/>} {tab==='stores'&&<Stores stores={stores} items={data.storeInventory||items} p={p} setModal={setModal} api={api}/>} {tab==='audit'&&<SystemAudit auditLogs={data.auditLogs||[]} api={api}/>} {tab==='rbac'&&<RBAC users={data.users} roles={data.roles} stores={stores} p={p} setModal={setModal} setSelected={setSelected} api={api}/>} {tab==='reports'&&<Reports currency={currency} items={items} stores={stores} categories={data.categories} transactions={transactions} taxRate={taxRate}/>} {tab==='settings'&&<SettingsPanel user={data.user} settings={data.settings} p={p} api={api} notify={notify}/>} {tab==='posted-notes'&&<PostedNotes notes={data.postedNotes||[]} api={api} p={p}/>}{false&&<div className="panel"><h2>System settings</h2><p className="muted">File-backed persistence is suitable for a single-server deployment. Configure SESSION_SECRET in production. For multiple instances, move persistence to PostgreSQL or another transactional database.</p><p><b>Authenticated as:</b> {user.email}</p></div>}</main>{modal==='item'&&<ItemModal item={selected} stores={stores} categories={data.categories} close={()=>setModal(null)} api={api}/>} {modal==='movement'&&<MovementModal item={selected} items={items} stores={stores} p={p} close={()=>setModal(null)} api={api}/>} {modal==='store'&&<StoreModal close={()=>setModal(null)} api={api}/>} {modal==='user'&&<UserModal user={selected} roles={data.roles} stores={stores} close={()=>setModal(null)} api={api}/>} {modal==='role'&&<RoleModal role={selected} close={()=>setModal(null)} api={api}/>} </div>
}
function Dashboard({items,stores,transactions,currency}:Any){
 const [range,setRange]=useState(30);
 const [storeFilter,setStoreFilter]=useState('All');
 const [chartMode,setChartMode]=useState<'sales'|'profit'>('sales');
 const scopedItems=storeFilter==='All'?items:items.filter((i:Any)=>i.storeId===storeFilter);
 const scopedTransactions=storeFilter==='All'?transactions:transactions.filter((t:Any)=>t.storeId===storeFilter||t.targetStoreId===storeFilter);
 const scopedValuation=scopedItems.reduce((n:number,i:Any)=>n+i.quantity*(i.sellPrice??i.unitPrice??0),0);
 const scopedUnits=scopedItems.reduce((n:number,i:Any)=>n+Number(i.quantity||0),0);
 const scopedLow=scopedItems.filter((i:Any)=>i.status==='Low Stock').length;
 const scopedOut=scopedItems.filter((i:Any)=>i.status==='Out of Stock').length;
 const now=new Date();
 const cutoff=new Date(now);
 cutoff.setDate(cutoff.getDate()-range);
 const recent=transactions.filter((t:Any)=>new Date(t.timestamp)>=cutoff && (storeFilter==='All'||t.storeId===storeFilter));
 const periods=range===365
   ? Array.from({length:12},(_,i)=>{const d=new Date(now.getFullYear(),now.getMonth()-11+i,1);const next=new Date(d.getFullYear(),d.getMonth()+1,1);return {d,next,label:d.toLocaleDateString(undefined,{month:'short',year:'numeric'})};})
   : Array.from({length:range},(_,i)=>{const d=new Date(now);d.setHours(0,0,0,0);d.setDate(d.getDate()-(range-1-i));const next=new Date(d);next.setDate(next.getDate()+1);return {d,next,label:d.toLocaleDateString(undefined,{month:'short',day:'numeric'})};});
 const trend=periods.map(({d,next,label})=>{
   const periodTx=recent.filter((t:Any)=>{const x=new Date(t.timestamp);return x>=d&&x<next;});
   const sales=periodTx.filter((t:Any)=>t.type==='OUT').reduce((n:number,t:Any)=>n+Number(t.totalValue??t.qty*(t.sellPrice??t.unitPrice??0)),0);
   const profit=periodTx.filter((t:Any)=>t.type==='OUT').reduce((n:number,t:Any)=>n+Number(t.profit??0),0);
   const unitsOut=periodTx.filter((t:Any)=>t.type==='OUT').reduce((n:number,t:Any)=>n+Number(t.qty||0),0);
   return {date:label,sales,profit,unitsOut};
 });
 const statusData=[
   {name:'In Stock',value:scopedItems.filter((i:Any)=>i.quantity>i.minThreshold).length},
   {name:'Low Stock',value:scopedItems.filter((i:Any)=>i.quantity>0&&i.quantity<=i.minThreshold).length},
   {name:'Out of Stock',value:scopedItems.filter((i:Any)=>i.quantity<=0).length}
 ].filter(x=>x.value>0);
 const categoryData=Array.from(new Set(scopedItems.map((i:Any)=>i.category).filter(Boolean))).map((category:any)=>({name:category,value:scopedItems.filter((i:Any)=>i.category===category).reduce((n:number,i:Any)=>n+i.quantity*(i.sellPrice??i.unitPrice??0),0)})).filter((x:Any)=>x.value>0).sort((a:any,b:any)=>b.value-a.value).slice(0,8);
 const topItems=scopedItems.map((i:Any)=>({name:i.name.length>22?`${i.name.slice(0,22)}…`:i.name,value:i.quantity*(i.sellPrice??i.unitPrice??0),qty:i.quantity})).filter((x:Any)=>Number(x.value)>0).sort((a:any,b:any)=>b.value-a.value).slice(0,8);
 const storeData=stores.map((s:Any)=>({name:s.code,value:items.filter((i:Any)=>i.storeId===s.id).reduce((n:number,i:Any)=>n+i.quantity*(i.sellPrice??i.unitPrice??0),0),units:items.filter((i:Any)=>i.storeId===s.id).reduce((n:number,i:Any)=>n+i.quantity,0)})).filter((x:Any)=>storeFilter==='All'||stores.find((s:Any)=>s.code===x.name)?.id===storeFilter).filter((x:Any)=>Number(x.value)>0||Number(x.units)>0);
 const recentSales=recent.filter((t:Any)=>t.type==='OUT').reduce((n:number,t:Any)=>n+Number(t.totalValue??t.qty*(t.sellPrice??t.unitPrice??0)),0);
 const recentProfit=recent.filter((t:Any)=>t.type==='OUT').reduce((n:number,t:Any)=>n+Number(t.profit??0),0);
 const recentUnitsOut=recent.filter((t:Any)=>t.type==='OUT').reduce((n:number,t:Any)=>n+Number(t.qty||0),0);
 const trendHasData=trend.some((x:Any)=>Number(x[chartMode]||0)!==0);
 const statusHasData=statusData.length>0;
 const topItemsHasData=topItems.length>0;
 const storeHasData=storeData.length>0;
 const categoryHasData=categoryData.length>0;
 return <div className="grid dashboard-grid">
   <div className="grid cards"><Metric label="Inventory Valuation" value={money(scopedValuation,currency)} sub={storeFilter==='All'?'Current on-hand value':'Selected store value'}/><Metric label="Units on Hand" value={scopedUnits.toLocaleString()} sub={storeFilter==='All'?'Across all stores':'Selected store'}/><Metric label="Low Stock" value={scopedLow} sub="At or below threshold" tone="amber"/><Metric label="Out of Stock" value={scopedOut} sub="Requires replenishment" tone="red"/></div>
   <div className="panel dashboard-controls"><div><b>Dashboard analytics</b><div className="muted">Interactive operational view of inventory and recent sales.</div></div><div className="toolbar" style={{margin:0}}><select value={storeFilter} onChange={e=>setStoreFilter(e.target.value)}><option value="All">All stores</option>{stores.map((s:Any)=><option key={s.id} value={s.id}>{s.name}</option>)}</select><div className="segmented"><button className={range===7?'active':''} onClick={()=>setRange(7)}>7 days</button><button className={range===30?'active':''} onClick={()=>setRange(30)}>30 days</button><button className={range===365?'active':''} onClick={()=>setRange(365)}>12 months</button></div></div></div>
   {trendHasData||statusHasData?<div className="grid two">
    {trendHasData&&<div className="panel"><div className="toolbar"><div style={{marginRight:'auto'}}><h2 style={{margin:0}}>{chartMode==='sales'?'Sales trend':'Profit trend'}</h2><div className="muted">Recent {range===365?'12 months':`${range} days`} · use the controls to change the view.</div></div><div className="segmented"><button className={chartMode==='sales'?'active':''} onClick={()=>setChartMode('sales')}>Sales</button><button className={chartMode==='profit'?'active':''} onClick={()=>setChartMode('profit')}>Profit</button></div></div><div className="chart tall"><ResponsiveContainer><AreaChart data={trend}><defs><linearGradient id="salesFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopOpacity={0.35}/><stop offset="100%" stopOpacity={0}/></linearGradient><linearGradient id="profitFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopOpacity={0.3}/><stop offset="100%" stopOpacity={0}/></linearGradient></defs><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="date"/><YAxis tickFormatter={(v)=>money(Number(v),currency).replace(/\.00$/,'')}/><Tooltip formatter={(v:any)=>money(Number(v),currency)}/><Area type="monotone" dataKey={chartMode} strokeWidth={2} fill={chartMode==='sales'?'url(#salesFill)':'url(#profitFill)'} name={chartMode==='sales'?'Sales':'Profit'} /></AreaChart></ResponsiveContainer></div><div className="grid three mini-metrics"><Metric label="Period sales" value={money(recentSales,currency)} sub="Stock-out revenue"/><Metric label="Period profit" value={money(recentProfit,currency)} sub="Gross profit" tone={recentProfit>=0?'green':'red'}/><Metric label="Units issued" value={recentUnitsOut.toLocaleString()} sub="Stock-out quantity"/></div></div>}
    {statusHasData&&<div className="panel"><h2>Stock status</h2><div className="chart"><ResponsiveContainer><PieChart><Pie data={statusData} dataKey="value" nameKey="name" innerRadius={58} outerRadius={92} paddingAngle={3} label={({name,value})=>`${name}: ${value}`}><Cell/><Cell/><Cell/></Pie><Tooltip/><Legend/></PieChart></ResponsiveContainer></div></div>}
   </div>:null}
   {topItemsHasData||storeHasData?<div className="grid two">
    {topItemsHasData&&<div className="panel"><h2>Top inventory value</h2><div className="chart tall"><ResponsiveContainer><BarChart data={topItems} layout="vertical" margin={{left:18,right:18}}><CartesianGrid strokeDasharray="3 3"/><XAxis type="number" tickFormatter={(v)=>money(Number(v),currency).replace(/\.00$/,'')}/><YAxis type="category" dataKey="name" width={130}/><Tooltip formatter={(v:any)=>money(Number(v),currency)}/><Bar dataKey="value" name="Inventory value" radius={[0,5,5,0]}/></BarChart></ResponsiveContainer></div></div>}
    {storeHasData&&<div className="panel"><h2>Inventory value by store</h2><div className="chart tall"><ResponsiveContainer><BarChart data={storeData}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="name"/><YAxis tickFormatter={(v)=>money(Number(v),currency).replace(/\.00$/,'')}/><Tooltip formatter={(v:any)=>money(Number(v),currency)}/><Bar dataKey="value" name="Inventory value"/></BarChart></ResponsiveContainer></div></div>}
   </div>:null}
   {categoryHasData&&<div className="panel"><h2>Valuation by category</h2><div className="chart"><ResponsiveContainer><BarChart data={categoryData}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="name"/><YAxis tickFormatter={(v)=>money(Number(v),currency).replace(/\.00$/,'')}/><Tooltip formatter={(v:any)=>money(Number(v),currency)}/><Bar dataKey="value" name="Inventory value"/></BarChart></ResponsiveContainer></div></div>}
   <div className="panel"><h2>Recent movements</h2>{scopedTransactions.slice(0,8).map((t:Any)=><div className="store-row" key={t.id}><div><b>{t.type}</b> · {t.itemId}<div className="muted">{t.recipient?`Issued to ${t.recipient} · `:''}{t.note}</div></div><span>{t.qty}</span></div>)}{!scopedTransactions.length&&<div className="empty">No movements found for this store.</div>}</div>
   {!trendHasData&&!statusHasData&&!topItemsHasData&&!storeHasData&&!categoryHasData&&<div className="panel"><div className="empty">No analytics data is available for the current dashboard filters. Charts will appear automatically when there is non-zero data.</div></div>}
 </div>
}
function Metric({label,value,sub,tone}:Any){return <div className="card"><div className="metric-label">{label}</div><div className={'metric '+(tone||'')}>{value}</div><div className="metric-sub">{sub}</div></div>}
function Inventory({currency,items,stores,categories,search,setSearch,status,setStatus,store,setStore,p,setModal,setSelected,api}:Any){return <div className="panel"><div className="toolbar"><input placeholder="Search SKU, name or barcode…" value={search} onChange={e=>setSearch(e.target.value)}/><select value={status} onChange={e=>setStatus(e.target.value)}><option>All</option><option>In Stock</option><option>Low Stock</option><option>Out of Stock</option></select><select value={store} onChange={e=>setStore(e.target.value)}><option value="All">All stores</option>{stores.map((s:Any)=><option key={s.id} value={s.id}>{s.name}</option>)}</select>{p('createItem')&&<button className="primary" onClick={()=>{setSelected(null);setModal('item')}}><Plus size={15}/> New SKU</button>}</div><div className="table-wrap"><table className="table"><thead><tr><th>SKU</th><th>Item</th><th>Type</th><th>Store</th><th>Qty</th><th>Buy</th><th>Sell</th><th>Status</th><th></th></tr></thead><tbody>{items.map((i:Any)=><tr key={i.id}><td><b>{i.id}</b><div className="muted">{i.barcode}</div></td><td>{i.name}<div className="muted">{i.category}</div></td><td>{i.itemType||'General'}</td><td>{stores.find((s:Any)=>s.id===i.storeId)?.name}</td><td>{i.quantity}</td><td>{money(Number(i.buyPrice??0),currency)}</td><td>{money(Number(i.sellPrice??i.unitPrice??0),currency)}</td><td><Status status={i.status}/></td><td><div className="actions">{p('adjustStock')&&<button className="secondary" onClick={()=>{setSelected(i);setModal('movement')}} title="Move stock"><ArrowRightLeft size={14}/></button>}{p('editItem')&&<button className="secondary" onClick={()=>{setSelected(i);setModal('item')}}><Edit size={14}/></button>}<button className="secondary" onClick={()=>printBarcode(i)} title="Print barcode"><Printer size={14}/></button>{p('deleteItem')&&<button className="danger" title="Disable stock" onClick={async()=>{const reason=await showPrompt('Reason for disabling this stock:','Stock disabled by authorised user','Disable stock');if(reason===null)return;await api('/api/items','PATCH',{id:i.id,status:'DISABLED',reason})}}><Power size={14}/></button>}</div></td></tr>)}</tbody></table></div>{!items.length&&<div className="empty">No inventory records match the current filters.</div>}</div>}
function Status({status}:Any){return <span className={'badge '+(status==='In Stock'?'green':status==='Low Stock'?'amber':'red')}>{status}</span>}
function ItemPicker({items,value,onChange,placeholder='Search item by SKU, name or barcode…',pageSize=8}:Any){
 const [query,setQuery]=useState(''),[page,setPage]=useState(1);
 const filtered=(items||[]).filter((i:Any)=>`${i.id} ${i.name} ${i.barcode||''} ${i.category||''}`.toLowerCase().includes(query.trim().toLowerCase()));
 const pages=Math.max(1,Math.ceil(filtered.length/pageSize));
 const safePage=Math.min(page,pages);
 const visible=filtered.slice((safePage-1)*pageSize,safePage*pageSize);
 useEffect(()=>setPage(1),[query]);
 useEffect(()=>{if(page>pages)setPage(pages)},[pages,page]);
 const selected=items?.find((i:Any)=>i.id===value);
 return <div style={{display:'grid',gap:7}}>
  <input value={query} onChange={e=>setQuery(e.target.value)} placeholder={placeholder}/>
  <select value={value} onChange={e=>onChange(e.target.value)}>
   {!value&&<option value="">Select an item…</option>}
   {selected&&!visible.some((i:Any)=>i.id===selected.id)&&<option value={selected.id}>{selected.id} — {selected.name} (selected)</option>}
   {visible.map((i:Any)=><option key={i.id} value={i.id}>{i.id} — {i.name}{i.quantity!==undefined?` (available ${i.quantity})`:''}</option>)}
  </select>
  <div style={{display:'flex',alignItems:'center',justifyContent:'space-between',gap:8}}>
   <span className="muted" style={{fontSize:12}}>{filtered.length} item{filtered.length===1?'':'s'} found</span>
   {pages>1&&<div className="form-actions" style={{margin:0}}>
    <button type="button" className="secondary" disabled={safePage<=1} onClick={()=>setPage((x:number)=>Math.max(1,x-1))}>Previous</button>
    <span className="muted" style={{padding:'6px 4px',fontSize:12}}>Page {safePage} of {pages}</span>
    <button type="button" className="secondary" disabled={safePage>=pages} onClick={()=>setPage((x:number)=>Math.min(pages,x+1))}>Next</button>
   </div>}
  </div>
 </div>
}
function ReceiptBuilder({currency,items,stores,p,api,setTab,setLastReceipt,taxRate}:Any){
 const initialStore=items[0]?.storeId||stores[0]?.id||'';
 const [storeId,setStoreId]=useState(initialStore),[lines,setLines]=useState<Any[]>([]),[itemId,setItemId]=useState(items.find((i:Any)=>i.storeId===initialStore)?.id||''),[qty,setQty]=useState(1),[amount,setAmount]=useState(items.find((i:Any)=>i.storeId===initialStore)?.sellPrice??items.find((i:Any)=>i.storeId===initialStore)?.unitPrice??0),[recipient,setRecipient]=useState(''),[reference,setReference]=useState(''),[note,setNote]=useState(''),[customerPhone,setCustomerPhone]=useState(''),[taxInclusive,setTaxInclusive]=useState(false),[busy,setBusy]=useState(false);
 const storeItems=items.filter((i:Any)=>!storeId||i.storeId===storeId);
 const selected=storeItems.find((i:Any)=>i.id===itemId);
 function choose(id:string){setItemId(id);const i=storeItems.find((x:Any)=>x.id===id);if(i){setAmount(i.sellPrice??i.unitPrice??0);setQty(i.quantity>0?1:0)}}
 function addLine(){
  if(!selected)return notifyLocal('Select an item');
  const q=Number(qty),a=Number(amount);
  if(selected.quantity<=0)return notifyLocal(`No stock is available for ${selected.name}`);
  if(!Number.isInteger(q)||q<=0)return notifyLocal('Enter a whole-number quantity greater than 0');
  if(q>selected.quantity)return notifyLocal(`Only ${selected.quantity} units are available for ${selected.name}`);
  if(!Number.isFinite(a)||a<0)return notifyLocal('Enter a valid amount');
  if(lines.some(x=>x.itemId===selected.id))return notifyLocal('That item is already on the receipt. Edit its line instead.');
  setLines([...lines,{itemId:selected.id,name:selected.name,qty:q,amount:a,max:selected.quantity}]);
 }
 function notifyLocal(m:string){void showAlert('Validation',m,'warning')}
 function remove(id:string){setLines(lines.filter(x=>x.itemId!==id))}
 function updateLine(id:string,key:string,value:number){setLines(lines.map(x=>{if(x.itemId!==id)return x;const current=items.find((i:Any)=>i.id===id);const max=current?.quantity??x.max;return key==='qty'?{...x,qty:Math.min(Math.max(1,Number.isFinite(value)?Math.trunc(value):1),max),max}:{...x,[key]:value}}))}
 const subtotal=lines.reduce((n:number,x:Any)=>n+x.qty*x.amount,0);const rate=taxRate===undefined||taxRate===null||taxRate===''?null:(Number.isFinite(Number(taxRate))?Number(taxRate):null);const taxAmount=rate===null?0:(taxInclusive?(subtotal-(subtotal/(1+rate/100))):(subtotal*(rate/100)));const total=rate===null?subtotal:(taxInclusive?subtotal:subtotal+taxAmount);
 async function generate(){
  if(!lines.length)return notifyLocal('Add at least one item');
  if(!recipient.trim())return notifyLocal('Enter who the stock is issued to');
  for(const x of lines){const current=items.find((i:Any)=>i.id===x.itemId);const available=current?.quantity??0;if(!current)return notifyLocal(`${x.name} is no longer available in inventory`);if(available<=0)return notifyLocal(`${x.name} is now out of stock`);if(!Number.isInteger(x.qty)||x.qty<=0)return notifyLocal(`Enter a valid whole-number quantity for ${x.name}`);if(x.qty>available){setLines(lines.map((line:Any)=>line.itemId===x.itemId?{...line,max:available,qty:available}:line));return notifyLocal(`${x.name}: only ${available} units are currently available. The quantity has been adjusted.`)}if(!Number.isFinite(x.amount)||x.amount<0)return notifyLocal(`Enter a valid amount for ${x.name}`)}
  setBusy(true);const r=await api('/api/receipts','POST',{lines:lines.map(x=>({itemId:x.itemId,qty:x.qty,sellPrice:x.amount})),customerName:recipient,customerPhone,reference,note,taxInclusive,taxRate});setBusy(false);if(r?.receipt){setLastReceipt(r.receipt);window.open(r.receipt,'_blank');setLines([]);setRecipient('');setCustomerPhone('');setReference('');setNote('');setTaxInclusive(false);setTab('receipt-history')}
 }
 return <div className="grid two"><div className="panel form-surface"><div className="toolbar"><div><h2 style={{margin:0}}>Build stock-out receipt</h2><div className="muted">Add every item and quantity before posting the issue.</div></div></div><div className="form-grid"><Field label="Store"><select value={storeId} onChange={e=>{const next=e.target.value;const first=items.find((i:Any)=>i.storeId===next);setStoreId(next);setLines([]);setItemId(first?.id||'');setAmount(Number(first?.sellPrice??first?.unitPrice??0));setQty(first?.quantity>0?1:0)}}>{stores.map((s:Any)=><option key={s.id} value={s.id}>{s.name}</option>)}</select></Field><Field label="Item"><ItemPicker items={storeItems} value={itemId} onChange={choose} placeholder="Search SKU, item name, barcode…" pageSize={8}/></Field><Field label="Quantity"><input type="number" min={selected?.quantity>0?1:0} max={selected?.quantity??0} step="1" value={qty} disabled={!selected||selected.quantity<=0} onChange={e=>setQty(Math.min(Math.max(1,Number(e.target.value)||1),selected?.quantity??0))}/></Field><Field label="Sell price / item"><input type="number" min="0" step="0.01" value={amount} onChange={e=>setAmount(Number(e.target.value))}/></Field><div className="field"><label>Available stock<div className="readonly-field"><b>{selected?.quantity??0}</b> {selected?.quantity===1?"unit":"units"}</div></label></div></div><div className="form-actions"><button className="primary" onClick={addLine} disabled={!selected||selected.quantity<=0||busy}><Plus size={15}/> Add to receipt</button></div><hr/><div className="form-grid"><Field label="Customer name *"><input value={recipient} onChange={e=>setRecipient(e.target.value)} placeholder="Person / department / project"/></Field><Field label="Customer phone (optional)"><input value={customerPhone} onChange={e=>setCustomerPhone(e.target.value)} placeholder="e.g. +250 7xx xxx xxx"/></Field><Field label="Reference"><input value={reference} onChange={e=>setReference(e.target.value)} placeholder="Request / issue number"/></Field><Field label="Note" full><textarea rows={3} value={note} onChange={e=>setNote(e.target.value)} placeholder="Optional note"/></Field></div></div><div className="panel"><div className="toolbar"><div><h2 style={{margin:0}}>Receipt item list</h2><div className="muted">{lines.length} item{lines.length===1?'':'s'} · {money(total,currency)}</div></div></div>{!lines.length?<div className="empty">No items added yet. Select an item, enter its quantity and amount, then click Add to receipt.</div>:<div className="table-wrap"><table className="table"><thead><tr><th>Item</th><th>Qty</th><th>Amount</th><th>Total</th><th></th></tr></thead><tbody>{lines.map((x:Any)=><tr key={x.itemId}><td><b>{x.itemId}</b><div className="muted">{x.name}</div></td><td><input style={{width:70}} type="number" min="1" max={x.max} value={x.qty} onChange={e=>updateLine(x.itemId,'qty',Number(e.target.value))}/></td><td><input style={{width:95}} type="number" min="0" step="0.01" value={x.amount} onChange={e=>updateLine(x.itemId,'amount',Number(e.target.value))}/></td><td>{money(x.qty*x.amount,currency)}</td><td><button className="danger" onClick={()=>remove(x.itemId)}><Trash2 size={14}/></button></td></tr>)}</tbody></table></div>}<div className="receipt-total"><div style={{display:'flex',justifyContent:'space-between'}}><span>Subtotal</span><b>{money(subtotal,currency)}</b></div><div style={{display:'flex',justifyContent:'space-between'}}><span>{rate===null?'Tax rate not configured':`${taxInclusive?'Tax included':'Tax'} (${rate}%)`}</span><b>{money(taxAmount,currency)}</b></div><div style={{display:'flex',justifyContent:'space-between',fontSize:18,marginTop:6}}><span>Grand total</span><b>{money(total,currency)}</b></div></div><label style={{display:'flex',alignItems:'center',gap:8,marginTop:10}}><input type="checkbox" checked={taxInclusive} onChange={e=>setTaxInclusive(e.target.checked)}/> Tax inclusive</label>{rate===null&&<div className="muted" style={{marginTop:10}}>Set the tax rate in Settings before generating a receipt.</div>}<div className="form-actions"><button className="secondary" onClick={()=>setLines([])} disabled={!lines.length}>Clear list</button><button className="primary" onClick={generate} disabled={busy||!lines.length||rate===null}>{busy?'Generating…':'Generate receipt'}</button></div></div></div>}

function Movements({items,stores,transactions,p,setModal,setSelected}:Any){return <div className="panel"><div className="toolbar">{(p('adjustStock')||p('transferStock'))&&<button className="primary" onClick={()=>{setSelected(null);setModal('movement')}}><Plus size={15}/> New movement</button>}</div><div className="table-wrap"><table className="table"><thead><tr><th>Time</th><th>Type</th><th>SKU</th><th>Qty</th><th>User</th><th>Issued to</th><th></th></tr></thead><tbody>{transactions.map((t:Any)=><tr key={t.id}><td>{new Date(t.timestamp).toLocaleString()}</td><td><span className="badge blue">{t.type}</span></td><td>{t.itemId}</td><td>{t.qty}</td><td>{t.user}</td><td>{t.recipient||'—'}</td><td>{t.type==='OUT'&&p('viewReceipts')&&<a href={`/receipts/${t.id}`} target="_blank" className="secondary" style={{display:'inline-flex',alignItems:'center',gap:5,textDecoration:'none'}}><Receipt size={14}/> Receipt</a>}</td></tr>)}</tbody></table></div></div>}
function ReceiptHistory({currency,receipts,transactions,stores}:Any){const [q,setQ]=useState(''),[from,setFrom]=useState(''),[to,setTo]=useState(''),[store,setStore]=useState('All');const receiptStoreIds=Array.from(new Set((receipts||[]).map((r:Any)=>r.storeId).filter(Boolean))) as string[];const filtered=(receipts||[]).filter((r:Any)=>{const hay=`${r.id} ${r.number||''} ${r.customerName||''} ${r.customerPhone||''} ${r.reference||''}`.toLowerCase();const d=new Date(r.timestamp);const okFrom=!from||d>=new Date(`${from}T00:00:00`);const okTo=!to||d<=new Date(`${to}T23:59:59`);return hay.includes(q.toLowerCase())&&okFrom&&okTo&&(store==='All'||r.storeId===store)});return <div className="panel"><div className="toolbar"><div><h2 style={{margin:0}}>Receipt history</h2><div className="muted">Search and filter completed receipts.</div></div></div><div className="toolbar"><input placeholder="Search receipt, customer, phone or reference…" value={q} onChange={e=>setQ(e.target.value)}/><input type="date" value={from} onChange={e=>setFrom(e.target.value)} title="From date"/><input type="date" value={to} onChange={e=>setTo(e.target.value)} title="To date"/><select value={store} onChange={e=>setStore(e.target.value)}><option value="All">All stores</option>{receiptStoreIds.map((id:string)=><option key={id} value={id}>{stores.find((s:Any)=>s.id===id)?.name||id}</option>)}</select></div>{!filtered.length?<div className="empty">No receipts match the current search or filters.</div>:<div className="table-wrap"><table className="table"><thead><tr><th>Date</th><th>Receipt</th><th>Customer</th><th>Phone</th><th>Items</th><th>Subtotal</th><th>Tax rate</th><th>Tax</th><th>Sales</th><th>Profit</th><th></th></tr></thead><tbody>{filtered.map((r:Any)=><tr key={r.id}><td>{new Date(r.timestamp).toLocaleString()}</td><td><b>{r.number||r.id}</b></td><td>{r.customerName}</td><td>{r.customerPhone||'—'}</td><td>{(r.transactionIds||[]).length}</td><td>{money(Number(r.subtotal??r.totalSales??0),currency)}</td><td>{r.taxRate===undefined||r.taxRate===null?'—':`${Number(r.taxRate)}%`}</td><td>{money(Number(r.taxAmount||0),currency)}</td><td>{money(Number(r.totalSales||0),currency)}</td><td>{money(Number(r.profit||0),currency)}</td><td><a className="secondary" href={`/receipts/${r.id}`} target="_blank" style={{textDecoration:'none'}}>View receipt</a></td></tr>)}</tbody></table></div>}</div>}

function Stores({stores,items,p,setModal,api}:Any){return <div className="grid three">{stores.map((s:Any)=>{const storeItems=items.filter((i:Any)=>i.storeId===s.id),disabled=storeItems.filter((i:Any)=>i.status==='Disabled');return <div className="panel" key={s.id}><h2>{s.name}</h2><div className="muted">{s.code}</div><p>{s.location}</p><p><b>Manager:</b> {s.manager||'—'}</p><p><b>Active SKUs:</b> {storeItems.filter((i:Any)=>i.status!=='Disabled').length}</p>{disabled.length>0&&<div style={{marginTop:14}}><b>Disabled stock ({disabled.length})</b><div className="table-wrap" style={{marginTop:8}}><table className="table"><thead><tr><th>SKU</th><th>Item</th><th>Status</th><th></th></tr></thead><tbody>{disabled.map((i:Any)=><tr key={i.id}><td>{i.id}</td><td>{i.name}<div className="muted">{i.disabledReason||'Disabled'}</div></td><td><Status status="Disabled"/></td><td>{p('deleteItem')&&<button className="secondary" onClick={async()=>{if(await showConfirm(`Enable ${i.name}?`,'Enable stock'))await api('/api/items','PATCH',{id:i.id,status:'ACTIVE'})}}>Enable</button>} {p('deleteItem')&&<button className="danger" onClick={async()=>{if(!(await showConfirm(`Permanently delete ${i.name}? This is only possible when there is no transaction history.`,'Delete stock')))return;await api('/api/items','DELETE',{id:i.id})}}><Trash2 size={14}/></button>}</td></tr>)}</tbody></table></div></div>}</div>})}{p('manageStores')&&<button className="primary" onClick={()=>setModal('store')} style={{minHeight:180}}>+ Add store</button>}</div>}
